import{_ as t,o as r,c as o,a2 as e}from"./chunks/framework.Cvf4Fkn6.js";const h=JSON.parse('{"title":"拖拽分屏与布局条","description":"","frontmatter":{},"headers":[],"relativePath":"guide/drag-snap.md","filePath":"guide/drag-snap.md","lastUpdated":1794577080000}'),n={name:"guide/drag-snap.md"};function i(s,a,l,d,g,p){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="拖拽分屏与布局条" tabindex="-1">拖拽分屏与布局条 <a class="header-anchor" href="#拖拽分屏与布局条" aria-label="Permalink to &quot;拖拽分屏与布局条&quot;">​</a></h1><p>拖拽分屏是 WTidy 的招牌交互，完整还原原版 Window Tidy：<strong>不用记快捷键、不用先想好布局——拖起窗口，选项自己出现</strong>。</p><h2 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h2><ol><li><strong>按住任意窗口的标题栏拖动</strong>，屏幕上浮现紧凑的<strong>布局图标条</strong>（每个图标对应一种布局，默认显示 8 种内置布局）</li><li><strong>瞄准在图标条内完成</strong>：鼠标在图标内的相对位置投影到布局区域——比如「左右半屏」图标偏左 = 左半屏、偏右 = 右半屏，单图标即可选区，鼠标行程最短</li><li><strong>悬停图标后整屏显示落点预览</strong>：目标区域高亮，松手前就能确认落点</li><li><strong>松手在图标上即吸附</strong>；也可把窗口移入屏内的分区高亮中精确选区</li><li>图标条之外的其他位置松手 = 正常拖拽，WTidy 完全不打扰</li></ol><h2 id="吸附动画" tabindex="-1">吸附动画 <a class="header-anchor" href="#吸附动画" aria-label="Permalink to &quot;吸附动画&quot;">​</a></h2><p>窗口吸附带平滑动画（常开行为，无需设置）。</p><p><strong>跨屏吸附自动分三阶段</strong>：先把窗口移到目标屏原点留出空间 → 调整尺寸 → 移到最终位置。大窗口直接跨屏移动时，屏幕会先裁掉超出部分，三阶段移动避免吸附途中被裁剪。</p><h2 id="图标条的外观与位置" tabindex="-1">图标条的外观与位置 <a class="header-anchor" href="#图标条的外观与位置" aria-label="Permalink to &quot;图标条的外观与位置&quot;">​</a></h2><p>图标条的全部呈现细节都在设置中可调：</p><ul><li><strong>配色主题</strong>：墨蓝 / 石墨 / 青碧 / 紫罗兰四套</li><li><strong>背景</strong>：默认深色底，或跟随桌面壁纸 + 蒙板</li><li><strong>位置</strong>：横 / 纵排列，屏幕边缘位置可视化预览 + 滑块微调，最大宽度、屏幕边距、窗口间隙</li><li><strong>临时隐藏</strong>：可在「行为」页选择按住 <code>⌥</code> 隐藏或按住 <code>⌥</code> 显示图标条</li></ul><p>详见<a href="./settings.html">设置页详解</a>。</p>',11)])])}const _=t(n,[["render",i]]);export{h as __pageData,_ as default};
